<!--
  App.vue - 应用根组件

  uni-app 的根组件仅用于注入全局样式，不包含业务逻辑。
  全局 SCSS 样式通过 @use 引入（含基础重置、中医主题色、字体等）。
-->
<template></template>

<script>
import { useAppStore } from '@/stores/app.js'

export default {
  onLaunch() {
    // #ifdef MP-WEIXIN
    // 微信小程序：动态加载楷体字体
    uni.loadFontFace({
      global: true,
      family: 'KaitiGB2312',
      source: 'url("data:font/ttf;charset=utf-8;base64,")',
      success() {
        console.log('KaitiGB2312 font loaded')
      },
      fail(err) {
        console.warn('KaitiGB2312 font load failed:', err)
      }
    })

    // 微信小程序：动态加载文源宋体（常规）
    uni.loadFontFace({
      global: true,
      family: 'WenYuanSerifSC',
      source: 'url("data:font/ttf;charset=utf-8;base64,")',
      success() {
        console.log('WenYuanSerifSC font loaded')
      },
      fail(err) {
        console.warn('WenYuanSerifSC font load failed:', err)
      }
    })
    // #endif

    // #ifdef APP-PLUS
    // App端：使用本地字体文件
    uni.loadFontFace({
      global: true,
      family: 'WenYuanSerifSC',
      source: 'url("/static/fonts/wenjinmincho-subset-v4.ttf")',
      success() {
        console.log('WenYuanSerifSC font loaded (App)')
      },
      fail(err) {
        console.warn('WenYuanSerifSC font load failed (App):', err)
      }
    })

    uni.loadFontFace({
      global: true,
      family: 'WenYuanSerifSC-Bold',
      source: 'url("/static/fonts/WenYuanSerifSC-Bold-subset-v2.ttf")',
      success() {
        console.log('WenYuanSerifSC-Bold font loaded (App)')
      },
      fail(err) {
        console.warn('WenYuanSerifSC-Bold font load failed (App):', err)
      }
    })
    // #endif
  },
  onShow() {
    // #ifdef APP-PLUS
    const store = useAppStore()
    store.syncSystemThemeFromDevice()
    store.applyThemeChrome()
    // #endif
  },
  onHide() {}
}
</script>

<style lang="scss">
@use '@/styles/index.scss';
</style>
